'Units_Guide_Note' => 'Kaliya halbeegyada aasaasiga ah ayaa loo dooran karaa "Base Unit", halbeegna lama tirtiri karo inta halbeeg-hoosaadyo ay weli isticmaalayaan.',
'Amount_Paid' => 'Lacagta la Bixiyay',
'Payment_Amounts_Help' => 'Lacagta la Bixiyay waxay dejisaa haraaga waxayna yareysaa Deynta. Lacagta la Helay waa lacagta caddaanka ah ee la soo dhiibay: waxaa kaliya loo isticmaalaa xisaabinta Baaqiga la celinayo, mana beddesho Deynta.',
'Show_Tax_Desc' => 'Canshuurta lagu dabaqay iibka oo dhan marka lacag-bixinta, oo lagu daabacay saf u gaar ah "Order Tax" wadarta.',
'Show_Items_Tax_Desc' => 'Wadarta canshuurta alaab kasta, oo lagu daabacay saf "Total Items Tax" ah. Marka la shido, wadar-hoosaadka waxaa lagu muujiyaa iyadoo canshuurahan laga reebay.',
'Show_Discount_Desc' => 'Dhimista lagu dabaqay iibka oo dhan (oo ay ku jirto dhimis kasta oo dhibco ah), oo lagu daabacay saf u gaar ah wadarta.',
'Show_Product_Discount_Desc' => 'Dhimista alaab kasta, oo lagu daabacay alaabtaas hoosteeda liiska shayada.',
'Receipt_Font_Family' => 'Farta Rasiidka',
'Receipt_Font_Family_Desc' => 'Farta loo isticmaalo dhammaan qoraalka rasiidka la daabacay. "Default" waxay haysaa farta caadiga ah ee rasiidka.',
'Receipt_Font_Size' => 'Cabbirka Farta Rasiidka (px)',
