'Additional_Information' => 'Macluumaad Dheeraad ah',
'Warehouses_Tab_Help' => 'Maaree bakhaarradaada (dukaamada/laamaha). Bakhaar kastaa wuxuu hayaa kaydkiisa, dukumenti kastana — iibka, iibsiyada, wareejinnada, hagaajinnada — waxaa loo diiwaangeliyaa mid ka mid ah.',
'Warehouse_Locations_Tab_Help' => 'Qeex goobaha khaanadaha / shelf-yada ee bakhaar kasta gudihiisa (tusaale Jidka 2 – Khaanadda B). U qoondee alaabooyinka si loo muujiyo meesha shayada jir ahaan loogu kaydiyay.',
