'Enable_Pos_Salesperson_Switch' => 'Beddel Iibiyaha Inta Lacag-bixinta Socoto',
'Enable_Pos_Salesperson_Switch_Hint' => 'Ku muuji doorashada iibiyaha shaashadda POS si iib loogu nisbeeyo shaqaale kale adigoon ka bixin. Iibiyaha la doortay waxaa lagu kaydiyaa qaansheegta waxaana loo isticmaalaa warbixinnada iibka; fadhiga POS ee firfircoon isma beddelo.',
'Wallet_Payment_Method_Missing' => 'Habka lacag-bixinta boorsada ayaa maqan',
'Wallet_Payment_Method_Missing_Help' => 'Lama helin hab lacag-bixin oo si sax ah loogu magacaabay "Wallet". Lacag-bixinta boorsada POS waxaa lagu waafajiyaa magacan, sidaa darteed macaamiishu kuma bixin karaan boorsadooda ilaa aad halkan ku darto hab lacag-bixin oo la yiraahdo "Wallet":',
'Show_Previous_Dues_Line' => 'Muuji Safka Deymihii Hore',
'Show_Previous_Dues_Line_Desc' => 'Haraagii macmiilku lagu lahaa ka hor iibkan. Waxaa la daabacaa oo kaliya marka uu ka badan yahay eber.',
'Show_Net_Balance_Line' => 'Muuji Safka Haraaga Saafiga ah',
'Show_Net_Balance_Line_Desc' => 'Deymihii hore oo lagu daray waxa weli lagu leeyahay iibkan. Waxaa la daabacaa oo kaliya marka deymihii hore ay ka badan yihiin eber.',
'QZ_Tray_Printer' => 'QZ Tray (daabace ku jira kombiyuutarkan)',
'QZ_Printer_Name_Hint' => 'Magaca daabacaha sida uga muuqdo kombiyuutarka QZ Tray ka socdo. Banaan uga tag si aad u isticmaasho daabacaha caadiga ah ee kombiyuutarkaas. Guji ⟳ si aad u ogaato daabacayaasha.',
'QZ_Not_Running' => 'QZ Tray kama socdo kombiyuutarkan. Ka rakib qz.io oo sii daa isagoo socda, kadibna u oggolow website-kan marka QZ ku weydiiyo.',
'Detect_Printers' => 'Ogow daabacayaasha',
'QZ_Download_Cert' => 'Soo deji shahaadada (override.crt)',
'QZ_Setup_Title' => 'Sida loo dejiyo daabacaadda QZ Tray (hal mar, kombiyuutar kasta oo calaamadaha daabaca)',
'QZ_Step_Install' => '1. Ku rakib QZ Tray kombiyuutarkan — ka soo deji bilaash qz.io, kadibna bilow oo sii daa isagoo socda (wuxuu ku jiraa system tray-ga Windows ama menu bar-ka macOS).',
'QZ_Step_Connect' => '2. Ku xir daabacahaaga calaamadaha USB oo hubi inuu ku rakiban yahay nidaamka hawlgalka (Windows: Settings > Printers & scanners — macOS: System Settings > Printers & Scanners).',
'QZ_Step_Detect' => '3. Guji badhanka ⟳ ee ku xiga "Magaca daabacaha" kor si aad u ogaato daabacayaasha kombiyuutarkan, kadibna dooro daabacahaaga calaamadaha. Banaan uga tag goobta si aad u isticmaasho daabacaha caadiga ah ee kombiyuutarka.',
'QZ_Step_Cert' => '4. Si aad u daabacdo adigoon helin daaqad oggolaansho, soo deji shahaadada hoose oo ku koobiyee galka rakibaadda QZ Tray, adigoo u beddelaya magaca override.crt (Windows: C:\\Program Files\\QZ Tray — macOS: /Applications/QZ Tray.app/Contents/Resources — Linux: /opt/qz-tray). Kadibna ka bax QZ Tray oo mar kale bilow.',
'QZ_Step_Test' => '5. Guji "Daabac calaamad tijaabo ah" hoose. Haddii QZ Tray uu oggolaansho weydiiyo, guji Allow — marka shahaadada la rakibo mar dambe ma weydiin doono.',
'QZ_Step_Save' => '6. Guji Gudbi si aad u kaydiso dejintan. Calaamadaha bogga Daabac Barcode hadda si toos ah ayay ugu daabacmi doonaan daabacahan, iyadoon jirin daaqad daabacaad browser.',
'QZ_Setup_Note' => 'QZ Tray wuxuu ka socdaa kombiyuutarka aad ka baadhayso, sidaa darteed tani way shaqeysaa xitaa marka Stocky lagu martigaliyo server fog. Kombiyuutar kasta oo calaamadaha daabaca wuxuu u baahan yahay in QZ Tray lagu rakibo.',
'PWA_Enabled' => 'Daar barnaamijka la rakibi karo',
'PWA_Enabled_Help' => 'Wuxuu u oggolaanayaa browser-yada inay soo jeediyaan rakibidda barnaamijkan taleefannada, tablet-yada iyo kombiyuutarrada, wuxuuna hayaa bogagga offline-ka ee kaydsan. Damintani waxay meel kasta ka saartaa codsiga rakibidda waxayna nadiifisaa kaydka booqashada xigta.',
'PWA_Identity' => 'Aqoonsiga barnaamijka',
'PWA_Launch' => 'Bilaabidda & muuqaalka',
'PWA_App_Name' => 'Magaca barnaamijka',
'PWA_App_Name_Help' => 'Wuxuu ka muuqdaa codsiga rakibidda iyo liiska barnaamijyada. Banaan uga tag si aad u isticmaasho magaca barnaamijka ee dejinta Muuqaalka.',
'PWA_Short_Name' => 'Magac gaaban',
'PWA_Short_Name_Help' => 'Wuxuu ka muuqdaa astaanta hoosteeda shaashadaha hoyga, halkaas oo magacyada dhaadheer la gooyo. Banaan uga tag si aad u isticmaasho qaybta magaca barnaamijka ee ka horreysa "|".',
'PWA_Description' => 'Sharaxaad',
'PWA_Description_Help' => 'Waxaa muujiya qaar ka mid ah dukaamada barnaamijyada iyo daaqadaha rakibidda.',
'PWA_Start_Url' => 'Bogga bilowga',
'PWA_Start_Url_Help' => 'Bogga barnaamijka la rakibay uu ka furmo, sida waddo ku bilaabata "/". Isticmaal /next/pos si aad toos ugu gasho POS-ka.',
'PWA_Display_Mode' => 'Habka muujinta',
'PWA_Display_Mode_Help' => 'standalone wuxuu qariyaa xariijinta browser-ka; fullscreen sidoo kale wuxuu qariyaa xariijinta xaaladda; browser wuxuu furaa tab caadi ah.',
'PWA_Orientation' => 'Jihaynta',
'PWA_Theme_Color' => 'Midabka mawduuca',
'PWA_Theme_Color_Help' => 'Wuxuu midabeeyaa xariijimaha nidaamka ee ku wareegsan barnaamijka la rakibay.',
'PWA_Background_Color' => 'Asalka shaashadda bilowga',
'PWA_Background_Color_Help' => 'Asalka shaashadda bilowga ee la muujiyo inta barnaamijku bilaabanayo.',
'PWA_Preview' => 'Horudhac',
'PWA_View_Manifest' => 'Eeg faylka manifest-ka',
'PWA_Reinstall_Notice' => 'Qalabka horay u rakibay barnaamijka waxay hayaan magacii iyo astaantii hore ilaa laga saaro oo mar kale la rakibo.',
'Label_Render_Mode' => 'Sawir-samaynta calaamadda',
'Label_Render_Mode_Hint' => 'Sida calaamadda loo sawiro. Farta daabacaha ayaa ugu dhakhsaha badan oo bixisa barcode-ka ugu fiiqan, laakiin waxay daabacdaa oo kaliya xarfaha Latin-ka aasaasiga ah farta daabacaha. Sawirka horudhaca wuxuu si sax ah u soo saaraa naqshadda calaamaddaada — farta aad dooratay, luqad kasta — sida software-ka calaamadaha gaarka ahi u sameeyo.',
'Render_Native' => 'Farta daabacaha (ugu dhakhsaha badan)',
'Render_Raster' => 'Sawirka horudhaca (naqshad sax ah)',
'Label_Width_Mm' => 'Ballaca calaamadda (mm)',
'Label_Height_Mm' => 'Jooga calaamadda (mm)',
'Label_Size_Hint' => 'Cabbirka jirka ah ee hal stiikar oo duubka ku jira. Waa inuu si sax ah ula mid noqdaa calaamadaha la geliyay — cabbir khaldan wuxuu daabacaha ka dhigaa inuu farqiga meel khaldan ka raadiyo, sidaa darteed calaamad kastaa way sii leexanaysaa.',
'Calibrate_Labels' => 'Cabbir-hagaaji calaamadaha',
'Calibrate_Labels_Hint' => 'Daabacuhu wuxuu soo saaraa calaamado yar si uu u cabbiro stiikarka iyo farqiga. Socodsii hal mar ka dib marka duub cusub la geliyo, ama marka meelaha daabacaaddu leexdaan.',
'Calibration_Sent' => 'Cabbir-hagaajintu way bilaabatay — daabacuhu wuxuu soo saari doonaa calaamado bannaan oo yar si uu u cabbiro. Marka uu joogsado, samee daabacaad tijaabo ah.',
'Label_Printer_Dpi' => 'Xallinta madaxa daabacaadda',
'Label_Printer_Dpi_Hint' => 'Daabacayaasha calaamadaha badankoodu waa 203 dpi. Ma hubtid? Isticmaal badhanka "Hel xallinta" ee hoose — wuxuu daabacaa jawaabta.',
'Find_Resolution' => 'Hel xallinta',
'Find_Resolution_Hint' => 'Wuxuu daabacaa laba calaamadood, oo lagu calaamadeeyay 203 iyo 300. Midda saxda ahi waxay stiikarka ku muujisaa afargeesle dhammaystiran oo leh geeso yar oo siman dhammaan afarta dhinac; midda khaldan waxay ka maqan tahay xuduudo ama waxay u gudubtaa stiikarka xiga.',
'Dpi_Test_Sent' => 'Laba calaamadood ayaa la daabacayaa, oo lagu calaamadeeyay 203 iyo 300. Midda saxda ahi waxay muujisaa afargeesle dhammaystiran oo leh geeso yar oo siman dhammaan afarta dhinac — "Xallinta madaxa daabacaadda" u deji lambarkaas oo kaydi.',
'Label_Offset_X' => 'Leexinta jiifka (mm)',
'Label_Offset_X_Hint' => 'Wuxuu daabacaadda u dhaqaajiyaa dhinac stiikarka. Isticmaal marka qoraalku ka go\'o hal gees — tusaale 2.5 marka stiikarka cad uu ku dhex yaal warqad asal ah oo ballaaran. Ku hagaaji tallaabooyin 0.5 ah.',
'Label_Offset_Y' => 'Leexinta taagga (mm)',
'Label_Offset_Y_Hint' => 'Wuxuu daabacaadda ku dhaqaajiyaa dhererka calaamadda. Kordhi marka naqshadda xaggeeda sare la gooyo ama maqan tahay; yaree marka ay ka bilaabato meel aad u hooseysa.',
'Feed_To_Tear' => 'U gudbi geesta jeexidda',
'Feed_To_Tear_Hint' => 'Wuxuu calaamadda u horumariyaa xariijinta jeexidda shaqo kasta ka dib. Ka dhig OFF haddii calaamaduhu u daabacmaan hoos u leexsan ama ay u kala qaybsamaan stiikarro — daabacayaal badan dib uma noqdaan ka hor calaamadda xigta.',
