'Store_URL_Path_Invalid' => 'Waddada URL-ka dukaanku ma ansax aha ama waxay ka hor imanaysaa waddo nidaam. Isticmaal xarfo, lambarro, jiitin ama hoos-xarriiq (tusaale "shop").',
