'Zatca_Phase_2_Help' => 'Phase 2 wuxuu saxiixaa qaansheegaadka wuxuuna u gudbiyaa madasha ZATCA Fatoora. Wuxuu u baahan yahay diiwaangelin leh OTP ka yimid bogga Fatoora.',
