'Shipping_Zone_Locations_Help' => 'Calaamadee aagga guud ee la isticmaalo marka aag kale uusan u dhigmin, ama qor dalalka (iyo ikhtiyaar ahaan gobollada) uu daboolo.',
'Shipping_Zone_Delete_Warning' => 'Aagga waa la saarayaa xeerarkiisana waa la joojinayaa. Dalabaadka jira waxay hayaan faahfaahintooda rarida.',
'Free_delivery' => 'Gaarsiin bilaash ah',
'Estimated_Delivery_Date' => 'Taariikhda gaarsiinta la filayo',
'Estimated_Delivery_Date_Hint' => 'Waxaa iibsadayaasha loogu muujiyaa "Gaarsiinta la filayo" kaarka iyo bogga alaabta. Banaan uga tag si aan waxba loo muujin. Alaabta dalab-horeyska ah tani sidoo kale waa taariikhda ay diyaar noqonayso.',
'Preorder_Uses_Delivery_Date' => 'Helitaanku wuxuu isticmaalaa taariikhda gaarsiinta la filayo ee lagu dejiyay qaybta Dukaanka ee kor ku xusan.',
'Related_Products' => 'Alaabooyinka la xiriira',
'Related_Products_Hint' => 'Dooro alaabooyinka ka muuqda "Alaabooyinka la Xiriira" ee boggan alaabta, sida ay u kala horreeyaan. Banaan uga tag si aad u isticmaasho xeerka tooska ah (isla qaybta, kadibna kuwa ugu cusub).',
'Enable_Wholesale_Pricing' => 'Qiimaha Jumlada Tiro ahaan',
'Enable_Wholesale_Pricing_Hint' => 'U oggolow alaabooyinka inay yeeshaan heerar tiro (10-19 xabbo, 20-49 xabbo, 100+ ...) oo si toos ah u beddela qiimaha tafaariiqda POS-ka iyo dukaanka online-ka marka tirada la dalbaday ay gaarto heer. Dami oo wax walba waxay mar kale ku iibmayaan qiimaha tafaariiqda caadiga ah — heerarka la habeeyay waa la hayaa, kaliya lama dabaqo.',
'Wholesale_Pricing_By_Quantity' => 'Qiimaha jumlada tiro ahaan',
'Wholesale_Pricing_By_Quantity_Hint' => 'Qiimaha xabbadkii marka tirada la dalbaday ay gaarto heer. Banaan uga tag kan ugu badan heerka sare ee furan (tusaale 100 iyo wixii ka badan). Heerka koowaad ka hooseeya alaabtu waxay ku iibmaysaa qiimaheeda tafaariiqda caadiga ah.',
'Wholesale_Pricing_Variants_Hint' => 'Hal jaranjaro ayaa daboosha alaabta oo dhan: nooc kasta waxaa lagu iibiyaa qiimaha heerka marka safkiisu gaaro heer.',
'Min_Quantity' => 'Tirada ugu yar',
'Max_Quantity' => 'Tirada ugu badan',
'Price_Per_Piece' => 'Qiimaha xabbadkii',
'Wholesale' => 'Jumlo',
'Wholesale_Tier_Applied' => 'Heer tiro jumlo ah ayaa khuseeya safkan',
'Orders_Guide' => 'Hagaha dalabaadka',
'Ord_Guide_Intro' => 'Sida dalab lagu dhigay dukaankaaga online-ka ugu socdo kaydkaaga iyo akoonnadaada, iyo meesha lacagta dhab ahaan lagu diiwaangeliyo.',
'Ord_Guide_Lifecycle_Title' => 'Xaaladda dalabka',
'Ord_Guide_Lifecycle_Pending' => 'Dalab cusub oo sugaya dib-u-eegistaada. Kaliya dalab sugaya ayaa la xaqiijin karaa ama la joojin karaa.',
'Ord_Guide_Lifecycle_Confirmed' => 'Waad aqbashay dalabka. Stocky wuxuu abuuraa Iib bakhaarka aad dooratay wuxuuna jaraa kaydka — iibkaasi waa diiwaanka ay ka akhriyaan warbixinnada kaydkaaga, lacag-bixintaada iyo faa\'iidadaada.',
'Ord_Guide_Lifecycle_Shipped' => 'Waad dirtay dalabka. Fulin kaliya: kaydka horay ayaa loo jaray markii aad xaqiijisay.',
'Ord_Guide_Lifecycle_Delivered' => 'Macmiilku wuu helay dalabka. Tani waa waxa bilaaba muddada celinta.',
'Ord_Guide_Lifecycle_Cancelled' => 'Dalabka waa la tuuray ka hor xaqiijinta, sidaa darteed iib lama abuurin kaydna lagama jarin.',
'Ord_Guide_PaymentStatus_Tip' => 'Waxaa la dejiyaa marka lacag-bixinta mana halkan laga beddeli karo. Guji si aad u aragto sida lacag-bixinta loo diiwaangeliyo.',
'Ord_Guide_Payment_Title' => 'Xaaladda lacag-bixinta',
'Ord_Guide_Payment_Intro' => 'Tiirkani wuxuu diiwaangeliyaa sida macmiilku u doortay inuu bixiyo marka lacag-bixinta. Waxaa dejiya dukaanka mana laga beddeli karo boggan — lacagta lafteeda waxaa lagu raadraacaa iibka ay abuurto xaqiijinta dalabka.',
'Ord_Guide_Payment_Paid' => 'Macmiilku horay ayuu online ugu bixiyay albaab lacag-bixin. Xaqiijinta dalabku waxay iibka u abuurtaa La Bixiyay waxayna kuu diiwaangelisaa lacag-bixinta — wax kale ma jiro oo la sameeyo.',
'Ord_Guide_Payment_Pending' => 'Lacag bixin marka la keeno, wareejin bangi ama hab kale oo dib loo bixiyo. Xaqiijinta dalabku waxay iibka u abuurtaa Aan la Bixin, sidaa darteed adigu diiwaangeli lacagta marka aad ururiso — eeg tallaabooyinka hoose.',
'Ord_Guide_Payment_Failed' => 'Albaabku wuu diiday lacag-bixinta ama macmiilku wuu ka tagay. Dalabka si toos ah ayaa loo joojinayaa.',
'Ord_Guide_MarkPaid_Title' => 'Beddelka lacag-bixinta laga bilaabo sugaya ilaa la bixiyay',
'Ord_Guide_MarkPaid_Step1' => 'Marka hore halkan ku xaqiiji dalabka — xaqiijintu waa waxa abuura iibka.',
'Ord_Guide_MarkPaid_Step2' => 'Fur Iibka > Dhammaan Iibka oo hel iibkaas (isla macmiilka, bogga faahfaahintuna wuxuu muujiyaa dalabka online-ka ee uu ka yimid).',
'Ord_Guide_MarkPaid_Step3' => 'Fur menuga ficillada safka oo dooro Abuur Lacag-bixin.',
'Ord_Guide_MarkPaid_Step4' => 'Geli lacagta, habka lacag-bixinta iyo taariikhda, kadibna kaydi. Iibku wuxuu iskiis ugu guuraa Qayb ahaan ama La Bixiyay, iyadoo ku xiran lacagta.',
'Ord_Guide_MarkPaid_Note' => 'Xaaladda Lacag-bixinta ee halkan ka muuqata waxay sii diiwaangelisaa doorashadii lacag-bixinta wayna sii ahaanaysaa sideeda. Iibku waa diiwaanka xisaabaadka, waana waxa quudiya warbixinnada lacag-bixintaada iyo faa\'iidadaada. Isticmaal Muuji Lacag-bixinta iibka si aad dib ugu eegto ama wax uga beddesho waxaad gelisay.',
'Ord_Guide_Notes_Title' => 'Waa wanaagsan tahay in la ogaado',
'Ord_Guide_Note_Warehouse' => 'Bakhaarka aad doorato marka la xaqiijinayo ayaa go\'aamiya meesha kaydka laga qaadayo. Bakhaarrada aan dabooli karin dalabka oo dhan waxaa liiskaas lagu calaamadeeyaa Kaydka ka dhammaaday.',
'Ord_Guide_Note_Preorder' => 'Shayada dalab-horeysku waxay ka gudbaan hubinta kaydka, sidaa darteed dalab ay ku jiraan waa la xaqiijin karaa xitaa marka tiradu aysan weli gacanta ku jirin.',
'Ord_Guide_Note_Flagged' => 'Calaamadda La calaamadeeyay waxay ka dhigan tahay in dalabku ku dhacay hubin khiyaano marka lacag-bixinta. Dul mari calaamadda si aad u aragto sababta oo dib u eeg dalabka ka hor intaadan xaqiijin.',
'Ord_Guide_Note_Cancel' => 'Joojintu waxay suurtagal tahay oo kaliya inta dalabku weli sugayo. Marka la xaqiijiyo, dib ugu celi iibka ama celin macmiil.',
