'Guide' => 'Hage',
'Variants_Guide' => 'Hagaha noocyada',
'VG_Intro' => 'Alaab noocyo leh waxaa loo iibiyaa noocyo dhowr ah. Ka dhis ikhtiyaarro (lagu taliyay) ama liis fudud oo magacyo ah. Nooc kastaa wuxuu leeyahay koodkiisa, qiimayaashiisa, sawirkiisa iyo kaydkiisa.',
'VG_Options_Title' => 'Habka ikhtiyaarrada (Midab, Cabbir...)',
'VG_Opt_Step1' => 'Furaha madaxa kaarka ku hay "Ikhtiyaarrada".',
'VG_Opt_Step2' => 'Qor magac ikhtiyaar sida Midab ama Cabbir, ama dooro mid ka mid ah soo jeedinnada.',
'VG_Opt_Step3' => 'Qor qiime (tusaale Casaan) oo riix Enter. Ku celi qiime kasta; comma sidoo kale way kala saartaa qiimayaasha. Guji x-da qiimaha si aad u saarto.',
'VG_Opt_Step4' => 'Guji "Ku dar ikhtiyaar" ikhtiyaar labaad ama saddexaad (ugu badnaan 3 ikhtiyaar).',
'VG_Opt_Step5' => 'Guji "Samee noocyada". Hal saf ayaa loo abuuraa isku-dhaf kasta magaciisana si toos ah ayaa loo dhisaa, tusaale "Red / S".',
'VG_Opt_Step6' => 'Geli kharashka iyo qiimaha saf kasta, ama qor qiime "U dabaq dhammaan" oo guji Kharash ama Qiimo si aad ugu koobiyeyso saf kasta.',
'VG_Opt_Step7' => 'Koodhadhka adiga ayaa laguu sameeyaa. Qor kaaga ama guji astaanta cusbooneysiinta si aad u samayso mid kale.',
'VG_Opt_Step8' => 'Ikhtiyaari: calaamadee "Muunadaha midabka" ikhtiyaar oo dooro midab qiime kasta; dukaanku wuxuu u muujiyaa dhibic midab leh.',
'VG_Rows_Title' => 'Safafka noocyada',
'VG_Rows_Text' => 'Saf kastaa wuxuu leeyahay sawir, kood, barcode, kharash, qiimo, qiimaha jumlada iyo qiimaha iibka ugu yar. Marka aad abuurayso alaab waxaad sidoo kale gelin kartaa kaydka bilowga bakhaar kasta nooc kasta. Calaamadda "Aan dhammaystirnayn" waxay ka dhigan tahay in safku ka maqan yahay qiime hal ikhtiyaar.',
'VG_List_Title' => 'Habka liiska fudud',
'VG_List_Text' => 'Qor magac nooc oo riix Enter (ama guji Ku dar) si aad ugu darto saf, kadibna buuxi koodkiisa iyo qiimayaashiisa. Tani waa habdhaqankii caadiga ahaa wayna u diyaar tahay alaabooyinka jira.',
'VG_Edit_Title' => 'Wax ka beddelka dambe',
'VG_Edit_1' => 'Ku dar qiime oo guji "Samee noocyada": kaliya isku-dhafyada maqan ayaa lagu daraa. Safafka jira waxay hayaan koodhadhkooda, qiimayaashooda iyo taariikhdooda.',
'VG_Edit_2' => 'Ka saarista qiime ama ikhtiyaar waxay saartaa safafka isticmaala. Safafka horay loo kaydiyay waa la tirtiraa marka aad kaydiso alaabta, xaqiijin ka dib.',
'VG_Edit_3' => 'Nooc weli kayd leh lama saari karo. Marka hore hagaaji ama wareeji kaydkiisa.',
'VG_Edit_4' => 'U beddelka "Liis fudud" wuxuu hayaa safafka iyo magacyadooda laakiin wuxuu tuuraa qeexitaannada ikhtiyaarka.',
'VG_Store_Title' => 'Dukaanka online-ka',
'VG_Store_Text' => 'Macaamiishu waxay doortaan hal qiime ikhtiyaar kasta, tusaale Midab kadibna Cabbir. Isku-dhafyada aan jirin waa la damiyaa kuwa kaydka ka dhammaadayna waa la xarriiqaa. Nooca la doortay ayaa gaariga gala.',
