'Upd_Note_Code_Changes_Lost' => 'Fiiro 1: Haddii aad gacanta wax ka beddeshay koodka isbeddelladaadu way lumi doonaan.',
'Upd_Manual_Steps_Intro' => 'Fadlan raac tallaabooyinkan si aad u cusboonaysiiso codsigaaga',
'Upd_Note_Permission_Only' => 'Fiiro 2: kaliya maamule ama isticmaale leh oggolaanshaha "{perm}" ayaa kor u qaadi kara nidaamka',
'Upd_Manual_Step_Backup_Db' => 'Samee kayd database-kaaga. Tag {backup}, guji Samee Kayd — waxaad ka heli doontaa {path} — ama ka dhoofi database-kaaga PhpMyAdmin oo ku kaydi kombiyuutarkaaga.',
