'Upd_Except' => 'marka laga reebo',
'Upd_File_Label' => 'fayl: {name}',
'Upd_Folder_Label' => 'gal: {name}',
'Upd_Manual_Step_Reupload' => 'Dib u soo geli faylasha iyo galalka cusboonaysiinta cusub, {except} isla saddexda waddo ee kor ku xusan.',
'Upd_Manual_Step_Visit' => 'Booqo {url} si aad u cusboonaysiiso database-kaaga.',
'Upd_Manual_Step_Clear_Cache' => 'Si adag u nadiifi kaydka browser-kaaga.',
'Upd_Manual_Step_Done' => 'Waad dhammeysay! Ku raaxayso codsiga la cusboonaysiiyay.',
'Upd_Note_Blank_Pages' => 'Fiiro: Haddii bogag aysan soo bixin ama ay madhan yihiin, hubi inaad nadiifisay kaydka browser-kaaga.',
'Upd_Guide_Before_Title' => '1. Ka hor inta aadan cusboonaysiin',
'Upd_Guide_Before_Download' => 'Ka soo deji {package} ee codsiga akoonkaaga CodeCanyon ({path}). Ha kala bixin — cusboonaysiiyuhu wuxuu u baahan yahay ZIP-ka sidii loo soo dejiyay.',
'Upd_Latest_Full_Zip' => 'xirmada ZIP ee ugu dambeysay oo dhammaystiran',
'Upd_Guide_Before_Admin' => 'Hubi inaad u gashay maamule leh oggolaanshaha {perm}. Qof kale ma arki karo mana socodsiin karo cusboonaysiiyaha.',
'Upd_Guide_Before_Quiet' => 'Dooro waqti xasilloon: inta lagu jiro cusboonaysiinta codsigu wuxuu u wareegayaa habka dayactirka muddo gaaban isticmaalayaasha kalena waa la xiraa.',
'Upd_Guide_Before_No_Manual' => 'Adigu {not} baahnid inaad gacanta ku sameyso kayd, kala bixiso faylal, socodsiiso amarro, wax ka beddesho faylasha dejinta, ama taabato database-ka — cusboonaysiiyaha ayaa si toos ah u qabta dhammaan. (Kayd dheeraad ah oo gacan ah weligiis waxyeello ma leh, dabcan.)',
'Upd_Not' => 'uma',
'Upd_Guide_Code_Overwritten' => 'Haddii aad gacanta wax ka beddeshay koodka codsiga, isbeddelladaada waa la dul qori doonaa cusboonaysiinta. Xogtaada, waxyaabaha la soo geliyay, dejinta iyo .env had iyo jeer waa la ilaaliyaa.',
'Upd_Guide_Running_Title' => '2. Socodsiinta cusboonaysiinta',
'Upd_Guide_Run_Open' => 'Fur {path} (boggan) oo ku jir tab-ka {tab}.',
'Upd_Guide_Run_Upload' => '{upload}: guji ama u jiid xirmada la soo dejiyay sanduuqa soo gelinta. Faylasha waaweyn waxaa loo soo geliyaa qaybo yaryar, sidaa darteed tani sidoo kale waxay ka shaqeysaa hosting la wadaago oo leh xad soo gelin yar. Checksum ayaa ka ilaaliya soo gelin xumaatay ama aan dhammaystirnayn.',
'Upd_Upload_The_Zip' => 'Soo geli ZIP-ka',
'Upd_Guide_Run_Validation' => '{auto} soo gelinta kadib (waxaad dib ugu socodsiin kartaa badhanka {button}). Nidaamku wuxuu hubiyaa: sugnaanta ZIP-ka, habdhismeedka iyo dhammaystirka xirmada, ku-habboonaanta nooca (hoos u dhigid waa la diidaa), nooca PHP iyo kordhinnada loo baahan yahay, oggolaanshaha faylasha, booska diskka ee bannaan, isku-xirka database-ka, dejinta, iyo in aysan socon cusboonaysiin kale.',
'Upd_Validation_Runs_Automatically' => 'Xaqiijintu si toos ah ayay u socotaa',
'Upd_Guide_Run_Review' => 'Dib u eeg guddiga {panel}. Badhanka {button} wuxuu soo baxaa oo keliya marka hubin kasta oo muhiim ah ay gudubto. Haddii hubin ay guul darreysato, fariintu waxay kuu sheegaysaa sax waxa la hagaajinayo.',
'Upd_Guide_Run_Click' => 'Guji {button} oo xaqiiji. Kadib si fudud {keep} oo daawo xariiqda horumarka. Nidaamku wuxuu sameeyaa, sida ay u kala horreeyaan:',
'Upd_Keep_Page_Open' => 'bogan furan u daa',
'Upd_Guide_Phase_Backup' => '{label} — kayd buuxa oo database-ka ah, ZIP ka kooban fayl kasta oo codsiga ah oo cusboonaysiintu beddeli karto, iyo nuqul {env} ayaa la abuuraa waana la {verified}. Waxyaabaha aad soo gelisay ({images}) iyo {storage} weligood cusboonaysiin ma taabato, sidaa darteed lama kaydiyo. Haddii kayd la abuuri waayo, cusboonaysiintu halkan ayay ku joogsanaysaa waxbana isma beddelaan.',
'Upd_Verified' => 'xaqiijiyaa',
'Upd_Guide_Phase_Prepare' => '{label} — nooca cusub waxaa lagu kala bixiyaa meel diyaarin ah oo mar kale ayaa la xaqiijiyaa. Codsiga nool weli lama taabto.',
'Upd_Guide_Phase_Maintenance' => '{label} — habka dayactirka waa la daaraa; booqdayaashu waxay arkaan shaashad saaxiibtinimo leh oo "Dhawaan ayaan soo laabanaynaa".',
'Upd_Guide_Phase_Files' => '{label} — faylasha cusub waxaa lagu beddelaa ku dhowaad isla markiiba; faylashii hore waxaa loo dhigaa dhinac si dib loogu celiyo. Waddooyinka la ilaaliyo ({env}, {storage}, {images}) weligood lama beddelo.',
'Upd_Guide_Phase_Database' => '{label} — migrations-ka ayaa socda, kadib oggolaanshaha, turjumaadda iyo tusaalooyinka waa la cusboonaysiiyaa.',
'Upd_Guide_Phase_Cache' => '{label} — dhammaan kaydadka ku-meel-gaarka ah waa la nadiifiyaa oo dib ayaa loo dhisaa.',
'Upd_Guide_Phase_Verify' => '{label} — hubinnada caafimaadka ayaa xaqiijiya in nooca cusub uu bilaabmo, database-ku shaqeeyo, dhammaan migrations-ku socdeen, dejintuna ansax tahay.',
'Upd_Guide_Phase_Done' => '{label} — habka dayactirka waa la qaadaa faylasha ku-meel-gaarka ahna waa la nadiifiyaa.',
'Upd_Guide_Run_Success' => 'Markaad aragto {success}, guji {reload} oo si adag u cusboonaysii browser-kaaga ({keys}) si ay u soo shubmaan agabka cusub ee guddiga maamulka.',
'Upd_Update_Successful_Short' => 'Cusboonaysiintu way guulaysatay',
'Upd_Guide_No_Internet' => 'Xiriir internet looma baahna inta lagu jiro cusboonaysiinta — wax walba waxay ka yimaadaan ZIP-ka la soo geliyay. Lumitaanka xiriirkaaga ama xiritaanka browser-ka MA JABINAYO cusboonaysiinta: server-ku wuxuu xasuustaa sax meesha uu ku joogsaday.',
'Upd_Guide_Wrong_Title' => '3. Haddii wax qaldamaan',
'Upd_Guide_Wrong_Rollback' => '{label} — haddii wax guul darreystaan kadib markii faylashu bilaabeen isbeddel (khalad kala bixid, guuldarro migration, hubin caafimaad oo dhacday, disk buuxa, …), nidaamku si toos ah ayuu u soo celiyaa faylashii hore iyo database-ka kaydka la xaqiijiyay, wuxuu qaadaa habka dayactirka, wuxuuna sheegaa {message}. Waxaad ku dhammaanaysaa sax meeshii aad ka bilowday.',
'Upd_Automatic_Rollback' => 'Dib-u-celin toos ah',
'Upd_Failed_Previous_Restored' => 'Cusboonaysiintu way guul darreysatay — nooca hore waa la soo celiyay',
'Upd_Guide_Wrong_Interrupted' => '{label} (dib u bilaabid server, waqti dhaaf, browser la xiray, koronto go\'day) — markaad dib u furto boggan, baanar casaan ah ayaa ku siinaya labo doorasho oo ammaan ah: {resume} (wuxuu ka sii wadaa sax tallaabadii uu ku joogsaday) ama {rollback} (wuxuu kaydka ka soo celiyaa nooca hore).',
'Upd_Interrupted_Update' => 'Cusboonaysiin go\'day',
'Upd_Guide_Wrong_Unreachable' => '{label} — isticmaal {console} gaarka ah ee {path}. Wuxuu shaqeeyaa xitaa marka goobtu ay ku jirto habka dayactirka ama agabka guddiga maamulku jabsan yihiin, wuxuuna bixiyaa isla ficillada Sii wad / Dib u celi. Waxaa sidoo kale jira link qarsoon oo "Gelitaanka maamulaha" ah oo ku yaal hoosta shaashadda dayactirka.',
'Upd_Admin_Unreachable' => 'Guddiga maamulka lama gaari karo',
'Upd_Recovery_Console' => 'konsoolka soo kabashada',
'Upd_Guide_Wrong_Locked_Out' => '{label} — inta cusboonaysiin socoto, boggan wuxuu muujinayaa {link}. Kaydi haddii aad u baahato inaad dib u gasho (tusaale kadib markii fadhigaagu dhacay); wuxuu kuu oggolaanayaa inaad dhaafto shaashadda dayactirka si aad mar kale u gasho.',
'Upd_Locked_Out_Maintenance' => 'Habka dayactirka ayaa kaa xiray',
'Upd_Bypass_Link' => 'link-ga dhaafitaanka',
'Upd_Guide_Wrong_Concurrent' => '{label} — waxay arki doonaan {message} Hal cusboonaysiin oo keliya ayaa mar walba socon karta.',
'Upd_Another_Admin_Updating' => 'Maamule kale ayaa isku dayaya inuu cusboonaysiiyo isla waqtiga',
'Upd_Guide_Backups_Title' => '4. Kaydadka & soo celinta',
'Upd_Guide_Backups_Created' => 'Cusboonaysiin kastaa waxay sameysaa kayd {before} inta aysan wax taaban: dhammaan faylasha codsiga ee cusboonaysiintu beddeli karto, nuqul {env}, iyo kayd buuxa oo database-ka ah. Waxyaabaha la soo geliyay iyo {storage} weligood cusboonaysiin wax kama beddesho sidaa darteed kama mid aha — samee kaydadkaaga gaarka ah ee kuwaas. Kaydadku waxay ku jiraan {path} weligoodna lagama heli karo web-ka.',
'Upd_Before' => 'ka hor',
'Upd_Guide_Backups_Panel' => 'Guddiga {panel} ee tab-ka {tab} wuxuu taxaa iyaga oo leh taariikh, nooc iyo cabbir. Halkaas waxaad ka {restore} kartaa kayd kasta oo dhammaystiran (faylal + database — nuqul badbaado ah oo database-ka hadda ayaa marka hore la qaadaa) ama {delete} kartaa kuwa duqoobay.',
'Upd_Restore_Verb' => 'soo celin',
'Upd_Delete_Verb' => 'tirtiri',
'Upd_Guide_Backups_Retention' => 'Isticmaal {keep} si aad u doorato inta kayd ee la hayo; kuwa duqoobay si toos ah ayaa loo saaraa cusboonaysiin kasta oo guulaysata kadib. Kaydka kaliya ee dhammaystiran ee haray weligiis lama tirtiri karo — had iyo jeer waxaad haysataa waddo aad dib ugu noqoto.',
'Upd_Guide_Manual_Title' => '5. Cusboonaysiin gacan ah (habka beddelka)',
'Upd_Guide_Manual_Text' => 'Haddii aad doorbidayso inaad gacanta ku cusboonaysiiso, ama soo geliyaha aan lagu isticmaali karin server-kaaga, raac tilmaamaha tallaabo-tallaabada ah ee tab-ka {tab} ee boggan.',
'Upd_Guide_Clear_Cache_First' => 'Haddii bogag u muuqdaan kuwo jaban ama madhan cusboonaysiin kasta kadib, marka hore nadiifi kaydka browser-kaaga — had iyo jeer ku dhowaad taasi waa sababta.',
'Upd_Restore_Backup_Confirm' => 'Ma soo celinaysaa kaydkan? Faylasha hadda iyo database-ka hadda waxaa lagu beddeli doonaa kaydka. Nuqul badbaado ah oo database-ka hadda ayaa marka hore la qaadaa. (v{version} — {date})',
'Woo_Guide_Lead' => 'Sida dukaan WooCommerce uu isula jaanqaado ERP-ga. Khadadka cron ee hoose waxaa loo dhisay server-kan, sidaa darteed si toos ah ayaa loogu koobiyeyn karaa.',
'Woo_Guide_Ways_Note' => 'Si ka duwan Shopify, WooCommerce waxba isagu uma diro ERP-ga — halkan ma jiro qaate webhook, sidaa darteed wax kasta oo {in} u soo galaya wuxuu yimaadaa jadwalka. Kaliya kaydka {out} u baxaya ayaa noqon kara isla markiiba.',
'Woo_In' => 'gudaha',
'Woo_Out' => 'dibadda',
'Woo_Guide_Both_Ways_Title' => 'Labada jihoba marka hore waxay u baahan yihiin tan',
'Woo_Api_Keys' => 'Furayaasha API',
'Woo_Guide_Api_Keys_Text' => '{path}, oggolaanshaha {perm}. Ku koobiyee consumer key iyo secret tab-ka {settings}, oo ay weheliso URL-ka dukaanka — cinwaanka goobtaada oo aan lahayn xariijin dambe, tusaale {example}.',
'Woo_Credentials_Saved' => 'aqoonsiga waa la kaydiyay',
'Woo_Not_Configured_Yet' => 'weli lama dejin',
'Woo_Guide_Wp_App_Password_Title' => 'Furaha codsiga WordPress (ikhtiyaari)',
'Woo_Guide_Wp_App_Password_Text' => 'Waxaa loo isticmaalaa oo keliya sawirrada alaabta. API-ga WooCommerce wuxuu raraa alaabta, kaydka, qaybaha, summadaha, macaamiisha iyo dalabyada; API-ga WordPress waa waxa ka raadiya Maktabadda Media oo soo geliya sawir aan weli halkaas ku jirin.',
'Woo_Guide_Wp_App_Password_Note' => 'Isticmaal isticmaale WordPress ah oo maamuli kara media, oo furaha ku abuur {path}. Labada goobood banaan u daa wax walbana weli waa la isku xirayaa — kaliya ku-lifaaqidda sawirka ayaa laga boodaa.',
'Woo_Guide_Pick_Way_Title' => 'Kadib dooro sida uu isula jaanqaado',
'Woo_Right_Away' => 'Isla markiiba',
'Woo_Stock_Live' => 'kaydka toos',
'Woo_Stock_Not_Live' => 'kaydka ma toosa',
'Woo_Guide_Realtime_Lead' => 'Hal jiho oo keliya: kaydka iyo alaabta ka baxaya ERP-ga. Dalabyada iyo wax ka beddelka alaabta ee lagu sameeyo WooCommerce weli waxay yimaadaan jadwalka — eeg tab-ka kale.',
'Woo_Push_Stock_On_Change' => 'Riix kaydka marka uu isbeddelo',
'Woo_Setting_People_Miss' => 'Tani waa dejinta ay dadku seegaan',
'Woo_Guide_Pos_Sale_Not_Reach' => 'Iibka POS {not} gaaro WooCommerce isagoo keligiis ah. Haddii la daminayo, dukaanku wuxuu ogaanayaa oo keliya isku-xidhka kaydka ee xiga — saacad, si caadi ah — muddadaas gudaheedna wuxuu iibin karaa unug aad horay ugu iibisay qasnadda.',
'Woo_Does_Not' => 'ma',
'Woo_Guide_Tick_Instant' => 'Calaamadee {option} ee tab-ka {settings}. Taasi waa dejinta oo dhan — worker ma jiro, cron ma jiro. Iib kasta, soo celin, hagaajin, wareejin iyo iibsi la helay waxay markaas diraan riixid oo keliya alaabtaas, isla marka iibka la kaydiyo kadib, iib labaatan saf ahna wuxuu ku kacaa hal riixid, ma aha labaatan. Qasnaddu weligeed ma sugto.',
'Woo_Currently' => 'Hadda:',
'Woo_Instant_On_Text' => 'daaran — kaydka waa la riixaa marka uu isbeddelo',
'Woo_Instant_Off_Text' => 'dansan — kaydka jadwalka oo keliya',
'Woo_Guide_Instant_Note' => 'Kaliya alaabta horay ugu xiran WooCommerce ayaa la riixaa — mid aan weligiis la isku xirin wax uu dukaanka ku saxo ma laha. Alaabta kala duwan waxay maraan waalidkooda, combo-na dib ayaa loo riixaa marka qaybihiisa midkood dhaqaaqo. Hawlgallada badan (tirtirka alaab, dib u dejinta bakhaar) waxay qoraan kayd iyagoon kicin dhacdo, taasina waa hal sabab oo loo hayo isku-xidhka kaydka saacadlaha ah.',
'Woo_Push_Products_On_Save' => 'Riix alaabta marka la kaydiyo',
'Woo_Guide_Tick_Auto_Products' => 'Calaamadee {option} ee tab-ka {settings} alaab lagu abuuray, wax laga beddelay ama la nuqulay Stocky waxaa loo diraa WooCommerce isla marka la kaydiyo kadib — faahfaahinta, qiimaha, noocyada iyo sawirrada, kadib kaydkeeda. Alaab cusub ayaa isla markiiba lagu abuuraa dukaanka halkii ay sugi lahayd isku-xidhka alaabta habeenkii.',
'Woo_On' => 'daaran',
'Woo_Off' => 'dansan',
'Woo_Guide_Bulk_Imports_Note' => 'Soo dejinta badan midba mid looma riixo — socodsii isku-xidhka alaabta soo dejinta kadib. Marka hore isku xir qaybaha iyo summadaha, si alaab la riixay ay ugu dhacdo qaybta saxda ah.',
'Woo_Nothing_Else_To_Install' => 'Wax kale oo la rakibo ma jiro',
'Woo_Guide_Same_Process' => 'Worker saf ma jiro, gelin cron ma jirto. Riixistu waxay ku socotaa isla habka u adeegay iibka, marka jawaabtu dib u laabato {after}, sidaa darteed qasnaddu weligeed ma sugto WooCommerce. Riixisyadu weligood isma dul maraan: isbeddellada la sameeyo inta mid socdo way sugaan oo isla markiiba kadib ayay baxaan.',
'Woo_After' => 'kadib',
'Woo_Guide_Shop_Stops_Answering' => 'Dukaan joojiya jawaab bixinta waa laga quustaa siddeed ilbiriqsi kadib, riixisyaduna waxay hakadaan shan daqiiqo si aan iib kastaa mar kale u sugin; isbeddellada inta lagu jiray yimid waxay la baxaan riixidda ugu horreysa ee hakadka kadib, isku-xidhka kaydka saacadlaha ahna wuu soo qabtaa si kastaba. Hakad kasta waxaa lagu diiwaangeliyaa tab-ka Diiwaannada.',
'Woo_Guide_Artisan_Exception' => 'Hal ka reeban: isbeddel kayd oo uu sameeyay amar artisan ma laha jawaab uu ka dambeeyo, sidaa darteed waxaa lagu dhex geliyaa safka {queue}. Si kuwaasna si degdeg ah u baxaan, madhi safkaas:',
'Woo_Cron_Line_Copied' => 'Khadka cron waa la koobiyeeyay',
'Woo_Command_Copied' => 'Amarka waa la koobiyeeyay',
'Woo_Guide_Not_Woo_Queue' => 'Si ula kac ah ma aha safka {queue}: kaasi wuxuu sidaa dufcadaha kataloogga ee saacadaha qaata, riixid degdeg ah oo gadaashooda safka gashana degdeg ma noqonayso.',
'Woo_On_A_Schedule' => 'Jadwal ku socda',
'Woo_Guide_Scheduled_Lead' => 'Wax walba dib ayaa loo hubiyaa mar mar, labada jihoba. Tani waa sida dalabyadu u gaaraan ERP-ga, sida kataloog loo daabaco, iyo waxa hagaajiya wax kasta oo jidka degdegga ahi seegay. Shaqo kastaa waxay leedahay gelin cron oo u gaar ah, sidaa darteed waxaad socodsiinaysaa oo keliya waxa aad rabto.',
'Woo_Guide_Sync_Drains_Queue' => '{command} wuxuu madhiyaa safkiisa inta uu socdo, sidaa darteed khadadkan uma baahna worker gaar ah. Windows, isticmaal Task Scheduler oo leh barnaamijka {program} iyo isla doodaha, oo laga bilaabay {path}.',
'Woo_Or_No_Cron' => 'Ama cron gabi ahaanba la\'aan',
'Woo_Guide_No_Cron_Text' => 'Tab kasta oo halkan ah wuxuu isku xiraa marka la codsado, isku-xidh gacan ahna wuxuu madhiyaa dufcadihiisa inta boggu furan yahay — sidaa darteed dukaan yar wuxuu ku shaqeyn karaa gelin cron la\'aan. Waxa aad lumineyso waa wax kasta oo dhaca inta aan cidi eegayn: dalabyadu waxay yimaadaan oo keliya marka qof riixo badhanka.',
'Woo_Commands_Worth_Knowing' => 'Amarro mudan in la ogaado',
'Woo_Worth_Knowing' => 'Mudan in la ogaado',
'Woo_Guide_Changing_Url_Clears' => 'Beddelidda URL-ka dukaanka ama furayaasha API waxay tirtiraysaa isku-xir kasta — alaabta, qaybaha, summadaha iyo macaamiisha dhammaan mar kale ayay ula xiriiraan dukaanka cusub.',
'Woo_Guide_Keep_Skus' => 'Ku hay SKU-yada si isku mid ah Stocky iyo WooCommerce: taasi waa waxa joojiya nuqullada oo ka dhiga dib-u-xiridda mid ammaan ah.',
'Woo_Guide_Stock_Total' => 'Kaydka loo daabaco Woo waa {total}, ma aha tirada hal bakhaar.',
'Woo_Total_Across_Warehouses' => 'wadarta dhammaan bakhaarrada',
'Woo_Guide_Full_Reference' => 'Tixraaca oo dhammaystiran — baaxad kasta, sida safku u dhaqmo, iyo liis xallinta dhibaatooyinka — wuxuu ku jiraa {file}.',
