'Woo_No_Shop_Connected' => 'Weli dukaan lama xirin',
'Woo_No_Shop_Connected_Desc' => 'Wax kasta oo hoose weli way khuseeyaan — geli URL-ka dukaanka iyo furayaasha API bogga dejinta WooCommerce, kadib soo noqo.',
'Woo_Wp_Username' => 'Magaca isticmaalaha WordPress',
'Woo_Wp_App_Password' => 'Furaha codsiga WordPress',
'Woo_Settings_Instant_Hint' => 'Iib, soo celin ama hagaajin waxay u diraan riixid kayd oo keliya alaabtaas isla marka la kaydiyo, sidaa darteed dukaanku wuxuu saxnaanayaa ilbiriqsiyo gudahood halkii uu ka sugi lahaa isku-xidhka kaydka saacadlaha ah ee xiga. Wax kale oo la rakibo ma jiro — riixistu waxay socotaa kadib marka iibka laga jawaabo, sidaa darteed qasnaddu weligeed ma sugto WooCommerce. Wax badan tab-ka {guide}.',
'Woo_Settings_Instant_Off_Alert' => 'Haddii la daminayo iibka POS wuxuu gaaraa WooCommerce oo keliya isku-xidhka kaydka ee xiga — ilaa saacad kadib.',
'Woo_Settings_Auto_Products_Hint' => 'Alaab lagu abuuray, wax laga beddelay ama la nuqulay Stocky waxaa loo diraa WooCommerce isla marka la kaydiyo kadib — faahfaahinta, qiimaha, noocyada, sawirrada, kadib kaydkeeda — halkii ay sugi lahayd isku-xidhka alaabta. Soo dejinta badan lama riixo; socodsii isku-xidhka alaabta soo dejinta kadib.',
'Woo_Sync_Tuning' => 'Hagaajinta isku-xidhka',
'Woo_Sync_Tuning_Intro' => 'Caadiyadu waxay ku habboon yihiin dukaamada intooda badan. Beddel kuwan oo keliya haddii isku-xidhku gaabis yahay ama uu waqtigu ka dhammaado hosting-kaaga. Qiime kastaa wuxuu ku xaddidan yahay xad ammaan ah, tirtiridda goobna waxay soo celinaysaa caadigeeda.',
'Woo_Setting_This_Up' => 'Dejinta tan',
'Woo_Setting_This_Up_Text' => 'Helitaanka furayaasha API, waxa furaha codsiga WordPress loogu talagalay, gelinnada cron ee isku-xidhka jadwaleysan, iyo sida kaydka loo gaarsiiyo dukaanka isla marka uu isbeddelo — dhammaan, oo leh khadadka cron ee server-kan oo diyaar u ah koobiyeynta, waxay ku jiraan tab-ka Hagaha. Hal nuqul, si aanu uga leexan waxa qaybtu dhab ahaan qabato.',
