'Salla_Guide_4' => 'Bogga Webhooks ee app-ka: dooro istaraatiijiyadda amniga {signature}, secret-keeda ku koobiyee goobta Webhook Secret ee halkan, deji Webhook URL-ka ka muuqda tabka Connection, oo ugu yaraan isku diiwaangeli {e1}, {e2}, {e3}, {e4}, {e5} iyo {e6}.',
