'Presta_Hero_Desc' => 'Isku waafaji alaabta, kaydka iyo dalabaadka dukaankaaga PrestaShop adigoo adeegsanaya webservice API-geeda.',
'Presta_Webservice_Key' => 'Furaha webservice-ka',
'Presta_Saved_Paste_New_Key' => 'La kaydiyay — dhig fure cusub si aad u beddesho',
'Presta_From_Menu' => 'Laga helo {menu}',
'Presta_Webservice_Key_Help' => 'Ka daar webservice-ka PrestaShop ({menu}), abuur fure leh oggolaanshaha products, stock_availables, orders iyo customers, kadibna halkan ku dhig. Waxaa loo kaydiyaa qoraal-kaliya.',
'Presta_Shop_Language_Id' => 'Shop language ID',
'Presta_Shop_Language_Help' => 'Aqoonsiga luqadda loo isticmaalo magacyada alaabta marka la dirayo (1 = luqadda koowaad ee dukaanka).',
'Presta_Push_Products_Desc' => 'Wuxuu PrestaShop ku abuuraa alaabta fudud ee maqan (oo leh kaydkooda hadda). Alaabta horey loo xiray iyo alaabta noocyada leh waa laga boodaa — sii wad wax ka beddelka faahfaahinta alaabta PrestaShop, ama soo jiid si aad u cusboonaysiiso nuqulka maxalliga ah.',
'Presta_Pull_Products_Desc' => 'Wuxuu soo dejiyaa alaabta PrestaShop, isagoo kuwa jira ku waafajinaya tixraaca (SKU) kuwa kalena abuuraya. Isku-darkooda (combinations) waxaa loo soo dejiyaa sidii alaabtooda waalidka.',
'Presta_Reset_Product_Confirm' => 'Dib u deji xiriirrada alaabta? Taariikhda dalabaadku way haysataa xiriirradeeda.',
'Presta_Push_Stock_Desc' => 'Wuxuu cusboonaysiiyaa kaydka dukaanka (stock_availables) alaab kasta oo la xiray.',
'Presta_Pull_Orders_Desc' => 'Wuxuu soo dejiyaa dalabaadka dukaanka iib ahaan (tixraacyo sida {ref}), kuwa ugu cusub marka hore. Dalabaadka horey loo soo dejiyay iyo kuwa la joojiyay waa laga boodaa, sidaa darteed soo jiidista joogtada ah waa ammaan. PrestaShop ma laha webhooks — ku socodsii waqtiyada mashquulka kadib.',
'Presta_Guide_1' => 'Back office-ka PrestaShop, fur {menu} oo daar webservice-ka.',
'Presta_Guide_2' => 'Ku dar fure cusub, adigoo siinaya {rw} {products} iyo {stock}, iyo {view} {orders} iyo {customers}.',
'Presta_Guide_3' => 'Ku dhig URL-ka dukaanka iyo furaha tabka Connection, kaydi, oo socodsii {test}.',
'Presta_Guide_4' => 'Marka hore soo jiid alaabta haddii dukaanku horey u leeyahay katalog (wuxuu ku waafajiyaa tixraac/SKU); u dir si aad u abuurto alaabta fudud ee maqan.',
'Presta_Guide_5' => 'U dir kaydka mar kasta oo tirooyinku isbeddelaan, oo si joogto ah u soo jiid dalabaadka — PrestaShop ma laha webhooks, sidaa darteed dalabaadku waxay yimaadaan kaliya marka aad soo jiidato.',
'Presta_Identity_Title' => 'Aqoonsiga alaabtu waa tixraaca (SKU)',
'Presta_Identity_Desc' => 'Koodhka alaabta Stocky waxaa lagu waafajiyaa tixraaca PrestaShop. Ka dhig tixraacyada kuwo isku mid ah labada dhinac; isku-darkooda (noocyada) waxaa dalabaadka lagu waafajiyaa tixraac laakiin looma diro nuqulkan.',
'Xero_Hero_Title' => 'Isku-waafajinta xisaabaadka Xero',
'Xero_Hero_Desc' => 'U dir macaamiishaada xiriirro Xero ahaan iyo iibkaaga qaansheegyo ahaan — oo leh lacag-bixinno marka akoon bangi la habeeyo.',
'Xero_App_Credentials_Accounts' => 'Aqoonsiyada app-ka & akoonnada',
