'Xero_Payment_Account_Help' => 'Koodh akoon bangi. Marka la dejiyo, iibka la bixiyay wuxuu sidoo kale qaansheegga ku diiwaangeliyaa lacag-bixin; banaan u daa si aad u isku waafajiso qaansheegyada oo kaliya.',
'Xero_Auto_Sync_Sales' => 'Si toos ah u isku waafaji iibka cusub qaansheegyo ahaan',
