'Xero_Disconnect_Confirm' => 'Ka goo ururka Xero? Isku-waafajintu way joogsanaysaa ilaa aad dib u xirto.',
'Xero_Redirect_Uri_Title' => 'Redirect URI-ga app-ka Xero',
'Xero_Redirect_Uri_Help' => 'Ku abuur "Web app" {link} oo ku diiwaangeli redirect URI-gan. Ogow: access token-nada Xero si toos ah ayay isu cusboonaysiiyaan, laakiin xiriir aan la isticmaalin in ka badan 60 maalmood waa in dib loo xiraa.',
'Xero_Total_Customers' => 'Wadarta macaamiisha',
