'Xero_Payments_Recorded' => 'Lacag-bixinnada la diiwaangeliyay',
'Xero_Push_Customers_To' => 'U dir macaamiisha {name}',
'Xero_Push_Customers_Desc' => 'Wuxuu abuuraa ama cusboonaysiiyaa xiriir Xero ah macmiil kasta. Macmiil magaciisu horey ugu jiro Xero waxaa lagu xiraa xiriirkaas.',
'Xero_Push_Customers' => 'U dir macaamiisha',
'Xero_Push_Sales_Invoices' => 'U dir iibka qaansheegyo ahaan',
'Xero_Push_Invoices_Desc' => 'Wuxuu abuuraa hal qaansheeg AUTHORISED ah iib kasta (lambarka qaansheegga = Ref-ka iibka), oo leh shayada iibka iyo safafka rarka, dhimista iyo canshuurta si wadarta Xero ay ula mid noqoto wadarta iibka. Iibka horey ugu jiray Xero waa laga boodaa — qaansheegyada weligood wax lagama beddelo. Xiriirrada maqan isla markaas ayaa la abuuraa.',
'Xero_Push_Invoices' => 'U dir qaansheegyada',
'Xero_Reset_Contact_Confirm' => 'Dib u deji xiriirrada contacts-ka? Dirista xigta ayaa dib u xireysa ama dib u abuureysa.',
'Xero_Reset_Contact_Links' => 'Dib u deji xiriirrada contacts-ka',
'Xero_Guide_1' => 'Ku abuur {webApp} {link} ({menu}).',
'Xero_Guide_2' => 'Diiwaangeli redirect URI-ga ka muuqda tabka Connection.',
'Xero_Guide_3' => 'Koobiyee {clientId} ee app-ka oo abuur {clientSecret}; labadaba halkan ku dhig kadibna kaydi.',
'Xero_Guide_4' => 'Riix {connect}, gal oo dooro ururka la xirayo.',
'Xero_Guide_5' => 'Hubi koodhadhka akoonnada: akoonka iibka wuxuu helaa safafka qaansheegga; deji koodh akoon bangi haddii iibka la bixiyay uu sidoo kale diiwaangelinayo lacag-bixinno.',
'Xero_Guide_6' => 'Marka hore u dir macaamiisha, kadibna qaansheegyada. Lambarrada qaansheegyadu waa Ref-yada iibka, sidaa darteed Xero waxay diidaysaa nuqullada xitaa haddii xiriirrada dib loo dejiyo.',
'Xero_Amounts_Title' => 'Qadarrada waxaa loo diraa iyagoo canshuurtu ku jirto sidooda',
'Xero_Amounts_Desc' => 'Qaansheegyadu waxay isticmaalaan safaf NoTax ah oo si sax ah u muujinaya iibka (shayada + rarka − dhimista + canshuurta), sidaa darteed wadarta Xero had iyo jeer waxay la mid tahay wadarta Stocky. Xisaabiyahaagu wuxuu safafka canshuurta iyo rarka u wareejin karaa akoonnada saxda ah gudaha Xero.',
'Xero_Org_Connected' => 'Ururka Xero waa la xiray.',
'Jumia_Hero_Title' => 'Isku-waafajinta suuqa Jumia',
'Jumia_Hero_Desc' => 'U dir qiimayaasha iyo kaydka liisaskaaga Jumia Seller Center oo dalabaadka suuqa u soo deji iib ahaan.',
'Jumia_Api_Url_Label' => 'API URL (endpoint-ka Seller Center ee dalkaaga)',
'Jumia_Account_Email' => 'Email-ka akoonka (User ID)',
'Jumia_Api_Key' => 'Furaha API',
'Jumia_Prices_Stock' => 'Qiimayaasha & Kaydka',
'Jumia_Push_Prices_Stock_Title' => 'U dir qiimayaasha & kaydka Jumia',
'Jumia_Push_Prices_Stock_Desc' => 'Wuxuu diraa qiimaha iyo tirada hadda ee alaab kasta (iyo nooc kasta) oo leh SKU la mid ah {sku} ee liiska Jumia. Cusboonaysiinta waxaa loo gudbiyaa sidii feeds Seller Center waxaana la dabaqaa si aan isku-waqti ahayn — feed ID-ga waxaa lagu diiwaangeliyaa tabka Logs, diidmooyinka shay kastana waxay ka muuqdaan shaashadda xaaladda feed-ka ee Seller Center.',
'Jumia_Push_Prices_Stock' => 'U dir qiimayaasha & kaydka',
'Jumia_Pull_Orders_Desc' => 'Wuxuu soo dejiyaa dalabaadka suuqa iib ahaan (tixraacyo sida {ref}), oo lagu waafajiyay alaabtaada Seller SKU. Dalabaadka horey loo soo dejiyay iyo kuwa la joojiyay waa laga boodaa, sidaa darteed soo jiidista joogtada ah waa ammaan. Lacag-bixinnada waxaa loo calaamadeeyaa la bixiyay kaliya dalabaadka la gaarsiiyay (Jumia inta badan waa COD).',
'Jumia_Guide_1' => 'Jumia {sellerCenter}, fur {menu} oo abuur furaha API.',
'Jumia_Guide_2' => 'Geli API URL-ka dalkaaga (tusaale {ng} Nigeria, {ke} Kenya, {eg} Masar), email-ka akoonkaaga Seller Center, iyo furaha — kadibna socodsii {test}.',
'Jumia_Guide_3' => 'Hubi in {sku} ee liis kasta oo Jumia uu la mid yahay koodhka alaabta Stocky — taasi waa aqoonsiga loo isticmaalo dirista kaydka iyo waafajinta dalabaadka labadaba.',
'Jumia_Guide_4' => 'U dir qiimayaasha & kaydka isbeddelka alaabta kadib; si joogto ah u soo jiid dalabaadka (Jumia ma laha webhooks API-gan).',
'Jumia_Guide_5' => 'Abuurista liisas cusub waxay ku hartaa Seller Center — Jumia waxay u baahan tahay astaamo gaar u ah qaybta iyo dib-u-eegis sawirro oo kaliya bogooda si fiican u qabto.',
'Mailchimp_Hero_Title' => 'Isku-waafajinta dhagaystayaasha Mailchimp',
'Mailchimp_Hero_Desc' => 'Ku buuxi dhagaystayaasha Mailchimp macaamiishaada, si aad ololeyaal email ugu sameyso macaamiishaada dhabta ah.',
