'Mailchimp_With_Email' => 'Leh email',
'Mailchimp_Push_Desc' => 'Wuxuu ku daraa ama cusboonaysiiyaa macmiil kasta oo leh ciwaan email dhagaystayaasha la doortay (magaca iyo telefoonka ay ku jiraan). Xubnaha jira waxay haystaan xaaladdooda is-diiwaangelinta — qof is-diiwaangelinta ka baxay dib looma diiwaangeliyo. Macaamiisha aan email lahayn waa laga tagaa.',
