'Mailchimp_Double_Optin_Off_Desc' => 'Xubnaha cusub waxaa loogu dari doonaa kuwo is-diiwaangeliyay iyadoo aan email xaqiijin ah la dirin. Tan u samee kaliya macaamiisha horey u oggolaaday inay helaan suuq-geyn.',
'Mailchimp_Guide_1' => 'Mailchimp, fur {menu} oo abuur fure (wuxuu ku dhammaadaa {suffix} — qaybtaas dambe waa datacenter-kaaga).',
'Mailchimp_Guide_2' => 'Halkan ku dhig furaha, kaydi, kadibna riix {load} oo dooro dhagaystayaasha la buuxinayo.',
'Mailchimp_Guide_3' => 'Daaran u daa {doubleOptIn} haddii aysan macaamiishaadu horey u oggolaan email-yada suuq-geynta.',
'Mailchimp_Double_Optin_Term' => 'double opt-in',
'Mailchimp_Guide_4' => 'Socodsii {push} buuxinta koowaad; daar {autoSync} si macaamiisha cusubi ay si toos ah ugu biiraan.',
'Mailchimp_Auto_Sync_Term' => 'isku-waafajin toos ah',
'Mailchimp_Consent_Title' => 'Oggolaanshuhu waa muhiim',
'Mailchimp_Consent_Desc' => 'U dirista email-yo dad aan weligood oggolaan suuq-geyn waxay jebin kartaa GDPR/CAN-SPAM waxayna keeni kartaa in akoonkaaga Mailchimp la hakiyo. Double opt-in wuxuu xaqiijinta u wareejiyaa Mailchimp — waa doorashada caadiga ah ee ammaanka ah.',
'Mailchimp_No_Audiences' => 'Akoonkan laguma helin dhagaystayaal.',
