'Shopify_G_Lead_Store' => 'Waxa dukaankani u baahan yahay si uu iskiis ula socdo. Wax kasta oo halkan ah waxay gaar u yihiin dukaankan — jidadka iyo aqoonsiyadu waa dhab, sidaa darteed amarrada si toos ah ayaa loogu koobiyeyn karaa server-ka.',
'Shopify_G_Lead_Generic' => 'Sida dukaan Shopify ah uu iskiis ula socdo ERP-ga. Kor ka dooro dukaan si aad u aragto xaaladdiisa, ama u akhri sida ay tahay — khadka cron-ka iyo webhook URL-ku waa isku mid dukaan kasta oo aad xirto.',
'Shopify_G_Ways_Note' => 'Dukaamada intooda badan waxay socodsiiyaan labadaba: kan koowaad wuxuu dukaanka ku hayaa mid cusub daqiiqad kasta, kan labaadna wuxuu qabtaa wixii kan koowaad ka dhaafay — webhook aan weligiis iman, wax ka beddel si toos ah loogu sameeyay maamulka Shopify, habeen goobtu dhacsanayd.',
'Shopify_G_Both_Need' => 'Labada jihoba marka hore waxay u baahan yihiin tan',
'Shopify_G_Credentials' => 'Aqoonsiyada Shopify',
'Shopify_G_Cred_Intro' => 'Laga bilaabo Janaayo 2026 Shopify kuma abuurto custom apps gudaha maamulka, sidaa darteed waxaa jira laba nooc oo xiriir ah:',
'Shopify_G_Cred_DevDash' => '{app} (dukaan kasta oo hadda la xiray) — {path}. Sii Admin API scopes-ka waxa dukaankani isku waafajiyo, ku rakib app-ka dukaanka, kadibna ka koobiyee {clientId} iyo {clientSecret} bogga Settings ee app-ka una gudbi {where}. ERP-gu iyaga ayuu iskiis ugu beddelaa access token wuxuuna cusboonaysiiyaa ka hor inta uusan dhicin 24-kii saacadoodba mar. Client secret-ku wuxuu sidoo kale saxiixaa webhooks, sidaa darteed waxba kale looma baahna. App-ka iyo dukaanku waa inay ku jiraan isla ururka Shopify.',
'Shopify_G_Dev_Dashboard_App' => 'App-ka Dev Dashboard',
'Shopify_G_Cred_Legacy' => '{app} (lagu abuuray maamulka ka hor 2026) — sidiisa ayuu u shaqeeyaa isagoo leh {token} ({prefix}) iyo {secret} sidii secret-ka saxiixa webhook-ga. Kani la mid maaha token-ka, isku qaldiddooduna waa sababta caadiga ah ee webhooks loo diido.',
'Shopify_G_Legacy_App' => 'Custom app hore',
'Shopify_G_API_Secret_Key' => 'API secret key',
'Shopify_G_Stored' => 'la kaydiyay',
'Shopify_G_Missing_Refused' => 'maqan — gaarsiinta waa la diidi doonaa',
'Shopify_G_Where_Data_Desc' => '{path} Bakhaarka ERP ee kaydkiisa dukaankani iibiyo, iyo goobta Shopify ee kaydkaas lagu qoro. Isku-waafajinta kaydka iyo soo dejinta dalabaadka labaduba way diidaan inay socdaan la\'aantood.',
'Shopify_G_Currently' => 'Hadda: bakhaarka {warehouse}, goobta {location}',
'Shopify_G_Not_Set_Lower' => 'lama dejin',
'Shopify_G_Ready' => 'diyaar',
'Shopify_G_Incomplete' => 'aan dhammaystirnayn',
'Shopify_G_Manual_Syncs' => 'Isku-waafajinta aad gacanta ku bilowdo',
'Shopify_G_Manual_Desc' => 'Isku-waafajin laga bilaabo {centre} isla markiiba way jawaabtaa waxayna gadaasha ka socotaa, qaybo gaagaaban oo mid kastaa ka sii wado meeshii tii hore ku joogsatay. Katalog weyn weligiis kama go\'o bartamaha hosting-ka joojiya codsiyada web-ka ee dheer (LiteSpeed, nginx, load balancer), xiritaanka bogguna ma joojiyo. Worker-ka taas waa hal khad cron oo kale:',
'Shopify_G_Cron_Copied' => 'Khadka cron waa la koobiyeeyay',
'Shopify_G_Manual_Note' => 'La\'aantiis isku-waafajintu weli way dhammaataa, laakiin kaliya inta bogga Sync Centre furan yahay: marka uusan worker qaadin socodsiin dhowr ilbiriqsi gudahood, bogga laftiisa ayaa sii wada, hal codsi gaaban markiiba. Windows isticmaal Task Scheduler daqiiqad kasta: barnaamijka {program}, doodaha {args}, laga bilaabo {dir}.',
'Shopify_G_Then_Pick' => 'Kadib dooro sida uu isula jaanqaado',
'Shopify_G_Right_Away' => 'Isla markiiba',
'Shopify_G_Stock_Live' => 'kaydka toos',
'Shopify_G_Stock_Not_Live' => 'kaydka ma toosa',
'Shopify_G_Realtime_Lead' => 'Isbeddel kasta waxaa la diraa markuu dhaco, ilbiriqsiyo gudahood. Laba qaybood, waana furayaal kala duwan: {webhooks} waxay keenaan dhacdooyinka dukaanka, {push}-na wuxuu diraa kaydka.',
'Shopify_G_Webhooks_Lower' => 'webhooks',
'Shopify_G_Instant_Push_Lower' => 'dirista kaydka degdegga ah',
'Shopify_G_Webhooks_In' => 'Webhooks — dukaanka → ERP-ga',
'Shopify_G_Webhooks_Desc' => 'Dalabaadka, isbeddelka xaaladda dalabka, iyo wax ka beddelka alaabta, macaamiisha iyo kaydka ee lagu sameeyo Shopify. Fur dukaanka oo riix {button} ee {tab} — laba jeer in la riixo waa ammaan. Shopify waxay u dirtaa:',
'Shopify_G_Webhooks_Tab' => 'Tabka Webhooks',
'Shopify_G_Webhooks_Note' => 'Ciwaanku waa inuu internet-ka ka gaari karo HTTPS — Shopify uma gaarsiiso {localhost} ama domain {test} ah. Gaarsiin kasta hal mar ayaa la diiwaangeliyaa, sidaa darteed dib-u-isku-dayga Shopify ma abuuri karaan dalab nuqul ah, mid guuldareystayna dib ayaa loo socodsiin karaa. Gaarsiinta waa la diidaa ilaa secret-ka saxiixa ee tallaabada 1 la kaydiyo.',
'Shopify_G_Instant_Out' => 'Dirista kaydka degdegga ah — ERP-ga → dukaanka',
'Shopify_G_Setting_Missed' => 'Tani waa dejinta ay dadku seegaan',
'Shopify_G_Pos_Not_Auto' => 'Iib POS ah {not} gaaro Shopify iskiis. Haddii la damiyo, dukaanku wuxuu ogaadaa kaliya tallaabada dirista Inventory ee xigta — muddadaasna wuxuu iibin karaa shay aad horey miiska ugu iibisay.',
'Shopify_G_Not' => 'uma',
'Shopify_G_Tick_Push' => 'Calaamadee {setting} ee {where}. Taasi waa diyaarinta oo dhan — worker ma jiro, cron ma jiro. Iib kasta, celin kasta iyo hagaajin kasta kadib waxay diraan dirid alaabtaas oo kaliya, isla marka iibka la kaydiyo kadib, iib labaatan saf ahna wuxuu ku kacaa hal dirid, ma aha labaatan. Khasnadu weligeed uma sugto.',
'Shopify_G_This_Store' => 'Dukaankan:',
'Shopify_G_Push_On' => 'daaran — kaydka waa la riixaa marka uu isbeddelo',
'Shopify_G_Push_Off' => 'dansan — kaydka jadwalka oo keliya',
'Shopify_G_Push_Note' => 'Kaliya alaabta horey u leh isku-aadin Shopify, iyo kaliya dhaqdhaqaaqa bakhaarka dukaankan, ayaa la diraa. Hawlaha badan — tirtirista alaab, dib u dejinta bakhaar — waxay qoraan kayd iyadoon dhacdo la kicin, taasina waa hal sabab oo loo hayo tallaabada kaydka ee jadwalaysan.',
'Shopify_G_Nothing_Install' => 'Wax kale oo la rakibo ma jiro',
'Shopify_G_No_Worker_Note' => 'Labada qaybood midna uma baahna queue worker ama cron. Webhook soo galaya waxaa lagu maareeyaa codsiga Shopify sameyso; kayd-dirid baxaysa waxay ku socotaa isla habsocodka u adeegay iibka, {after} marka jawaabtu dib u noqoto — sidaa darteed khasnadu weligeed uma sugto Shopify, dukaan joojiya jawaabtana waa laga quustaa toban ilbiriqsi kadib waxaana loo dayaa dirista kaydka jadwalaysan ee xigta.',
'Shopify_G_After' => 'kadib',
'Shopify_G_Artisan_Note' => 'Hal ka reeban: isbeddel kayd oo amar artisan sameeyay ma laha jawaab uu ka dambeeyo, sidaa darteed waxaa la safeeyaa {queue} halkii. Haddii aad rabto in kuwaasna si degdeg ah u baxaan, faaruqi queue-gaas:',
'Shopify_G_On_Schedule' => 'Jadwal ku socda',
'Shopify_G_On_Lower' => 'daaran',
'Shopify_G_Off_Lower' => 'dansan',
'Shopify_G_Scheduled_Lead' => 'Wax kasta dib ayaa loo hubiyaa waqti ka waqti, labada jiho. Way ka gaabisaa waqtiga dhabta ah, laakiin waa waxa kaydka u dira dukaamada aan isticmaalin dirista degdegga ah, waxa qabta webhook la seegay, iyo habka kaliya ee katalog dhan loo dhaqaajiyo.',
'Shopify_G_Cron_Entry' => 'Cron-ka',
'Shopify_G_Cron_Entry_Desc' => 'Waxba oo jadwalaysan ma socdaan la\'aantiis. Hal khad, moduulkan oo kaliya — ku dar agagaarka wax kasta oo kale oo aad dooratay inaad jadwaliso:',
'Shopify_G_Cron_Note' => 'Shan daqiiqo kasta waa xalka ugu yar ee qorshe isticmaali karo, sababtoo ah shan daqiiqo waa muddada tallaabo ee ugu gaaban. Cron ka sii ballaaran wuxuu noqdaa xadka hoose — {example}, tallaabo loo dejiyay 5 daqiiqo waxay socotaa 15-kii daqiiqoba mar. Windows isticmaal Task Scheduler: barnaamijka {program}, doodaha {args}, laga bilaabo {dir}.',
'Shopify_G_Switch_On_Plan' => 'Daar, oo dooro qorshaha',
'Shopify_G_Plan_Desc' => '{where} Furuhu wuxuu go\'aamiyaa in cron-ku wax qaban karo iyo in kale; qorshuhu wuxuu go\'aamiyaa waxa uu qabto. {step} waa hal hay\'ad oo hal jiho ah oo leh muddadeeda — {first}, {second}. Muddada caadiga ah waxaa isticmaala tallaabo kasta oo sanduuqeeda banaan u dhaafta.',
'Shopify_G_Step_Lower' => 'tallaabo',
'Shopify_G_Plan_Note' => 'Qorshaha banaan u daa dukaankuna wuxuu soo jiidaa dalabaadka wuxuuna diraa kaydka muddada caadiga ah, taas oo ah waxa dukaamada intooda badani rabaan. Dalabaadku waa soo-jiid kaliya: Shopify waa meesha macmiilku ku sameeyo.',
'Shopify_G_Schedule_On' => 'jadwalku waa daaran yahay',
'Shopify_G_Schedule_Off' => 'jadwalku waa dansan yahay — gacanta oo kaliya',
'Shopify_G_When_Step_Runs' => 'Marka tallaabo dhab ahaan socoto',
'Shopify_G_When_Note' => 'Tallaabo waa la gaaray marka isla tallaabadaas ay ugu dambeysay {started} waqti ka dheer muddadeeda, taas oo laga akhriyo taariikhda socodsiinta. Sidaa darteed isku-waafajin aad gacanta ku bilowdo waxay dib u dhigtaa tan toosta ah ee xigta, tallaabo had iyo jeer guuldareysanaysana dib ayaa loo isku dayaa muddadeeda halkii ay ka ahaan lahayd mar kasta. Overview-ga dukaanku wuxuu muujiyaa socodsiinta ugu dambeysay ee tallaabo kasta, waqtiga xiga ee la gaaro, iyo sababta loo xannibay marka ay xannibantahay. Dirista katalogga koowaad gacanta ku socodsii — marka hore {dryRun} — ka hor intaadan jadwal gelin.',
'Shopify_G_Started_Lower' => 'bilaabantay',
'Shopify_G_Where_Setting' => 'Meesha dejin kastaa ku taal',
'Shopify_G_Where_Setting_Note' => 'Kuwan oo dhan waxay ku yaalaan dukaan jira: {path}, kadibna qalinka (ama {edit} bogga dukaanka laftiisa).',
'Shopify_G_Product_Images' => 'Sawirrada alaabta',
'Shopify_G_Img_1' => 'Sawirradu waxay la baxaan alaabta marka {push} — sawirka ugu weyn marka hore, kadib gallery-ga, kadibna mid nooc kasta oo leh mid u gaar ah, ilaa konton.',
'Shopify_G_Products_Push' => 'la diro alaabta',
'Shopify_G_Img_2' => 'Sawirka nooca waxaa lala soo geliyaa alaabta kadibna waa {assigned}, taas oo ah sida Shopify u qaabeyso: nooc wuxuu tilmaamaa mid ka mid ah sawirrada alaabta. Nooc dib u isticmaalaya sawirka ugu weyn ma soo geliyo laba jeer.',
'Shopify_G_Assigned' => 'loo qoondeeyay noocaas',
'Shopify_G_Img_3' => 'Sawir ku kaydsan fayl ahaan waxaa {uploaded} Shopify, lama xiro, sidaa darteed wuu shaqeeyaa xitaa marka rakibaaddan aan internet-ka laga gaari karin. Sawir lagu daray link la dhejiyay waxaa Shopify loo dhiibaa URL-kaas, kaas oo ay tahay in si guud loo gaari karo.',
'Shopify_G_Uploaded' => 'loo soo geliyaa',
'Shopify_G_Img_4' => 'Dib ayaa loo diraa kaliya marka ay dhab ahaan isbeddelaan — dirid beddesha qiimaha oo kaliya sawirrada dukaanka ma taabato, sababtoo ah diristoodu waxay beddeshaa urursanaha oo dhan.',
'Shopify_G_Img_5' => 'Ka saarista sawir ERP-ga {not} tirtirto Shopify. Halkaasna ka tirtir, haddii kale dukaanku wuu sii muujinayaa.',
'Shopify_G_Commands' => 'Amarro mudan in la ogaado',
'Shopify_G_Command_Copied' => 'Amarka waa la koobiyeeyay',
'Shopify_G_Foot' => 'Isku-waafajin kastaa waxay wax ku qortaa {logs}, Overview-ga dukaan kastana wuxuu muujiyaa goorta tallaabo kasta ugu dambeysay socotay, goorta xigta ee la gaarayo, iyo waxa xannibaya marka ay jirto. Taasi waa meesha marka hore la eego marka isku-waafajin aysan samayn wixii aad filaysay.',
'Shopify_G_Covers' => 'Wuxuu daboolaa',
'Shopify_G_Covers_Rt' => 'Dalabaadka iyo wax ka beddelka lagu sameeyo Shopify; kaydka ka baxaya ERP-ga (iib POS, celin, hagaajin)',
'Shopify_G_Covers_Sch' => 'Wax kasta, labada jiho — oo ay ku jiraan dirista katalogga iyo wax kasta oo jidka degdegga ahi seegay',
'Shopify_G_Speed' => 'Xawaare',
'Shopify_G_Speed_Rt' => 'Ilbiriqsiyo',
