'StoreAdm_PG_Intro_Msg' => 'PayPal, Paystack, Flutterwave, Razorpay, bKash iyo SSLCommerz waxaa isticmaala kaliya lacag-bixinta DUKAANKA ONLINE-KA.',
'StoreAdm_PG_Intro_Desc' => 'Furayaasha Stripe waa la wadaagaa guud ahaan (maamulka iyo dukaanka online-ka waxay isticmaalaan isla isku-xirka Stripe). Tab kastaa wuxuu daaraa ama damiyaa habkiisa lacag-bixinta dukaanka online-ka; Offline Payments wuxuu hayaa hababka lagu bixiyo meel ka baxsan nidaamka.',
