'StoreAdm_PG_Webhook_Url' => 'Webhook URL:',
'StoreAdm_PG_Gw_Disabled' => '{gw} waa dansan yahay',
'StoreAdm_PG_Paypal_Disabled_Desc' => 'Daar PayPal oo geli Client ID iyo Secret-ka REST app-kaaga (laga helo {site}) si macaamiishu ugu bixin karaan PayPal lacag-bixinta dukaanka online-ka.',
'StoreAdm_PG_Gw_Public_Key' => '{gw} Public Key',
'StoreAdm_PG_Gw_Secret_Key' => '{gw} Secret Key',
'StoreAdm_PG_Paystack_Test_Live' => 'Tijaabo iyo dhab waxaa go\'aamiya labada fure: furayaasha {test} waxay ku shaqeeyaan habka tijaabada, furayaasha {live} waxay lacag ka qaadaan kaarar dhab ah — ma jiro fure sandbox oo gaar ah.',
'StoreAdm_PG_Paystack_Webhook_Url' => 'Webhook URL (kaabis ikhtiyaari ah — ku deji Settings → API Keys & Webhooks ee dashboard-ka Paystack; codsiyada waxaa lagu xaqiijiyaa HMAC iyadoo la adeegsanayo secret key-gaaga):',
'StoreAdm_PG_Paystack_Disabled_Desc' => 'Daar Paystack oo geli furayaashaada Public iyo Secret (laga helo {site} → Settings → API Keys) si aad u aqbasho kaararka, wareejinta bangiga iyo lacagta mobile-ka lacag-bixinta dukaanka online-ka.',
