'StoreAdm_PG_Flutterwave_Info' => 'Wuxuu isticmaalaa Flutterwave v3 API oo leh furayaal caadi ah. Tijaabo iyo dhab waxaa go\'aamiya labada fure ({keys} iyo furayaasha dhabta ah) — ma jiro fure sandbox oo gaar ah. Lacagta dukaanka waa in laga daaro akoonkaaga Flutterwave.',
