'StoreAdm_PG_Razorpay_Info' => 'Wuxuu isticmaalaa Razorpay Payment Links (kaarar, UPI, netbanking, wallets). Tijaabo iyo dhab waxaa go\'aamiya labada fure ({keys}) — ma jiro fure sandbox oo gaar ah.',
