'StoreAdm_PG_Bkash_Info' => 'Wuxuu isticmaalaa bKash Tokenized Checkout (aqoonsiyada ganacsadaha ee bogga ganacsadaha bKash). bKash wuxuu lacag ku qaadaa BDT oo kaliya — doorashada waxaa la bixiyaa lacag-bixinta kaliya inta lacagta firfircoon ee dukaanku tahay BDT.',
